import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class LRUCache {
        private static class Node {
            int key, value;
            Node prev, next;
            Node(int key, int value) { this.key = key; this.value = value; }
        }

        private final int capacity;
        private final Map<Integer, Node> mapa = new HashMap<>();
        private final Node head = new Node(0, 0);
        private final Node tail = new Node(0, 0);

        LRUCache(int capacity) {
            this.capacity = capacity;
            head.next = tail;
            tail.prev = head;
        }

        int get(int key) {
            var n = mapa.get(key);
            if (n == null) return -1;
            moverParaFrente(n);
            return n.value;
        }

        void put(int key, int value) {
            var n = mapa.get(key);
            if (n != null) {
                n.value = value;
                moverParaFrente(n);
                return;
            }
            if (mapa.size() == capacity) {
                var antigo = tail.prev;
                remover(antigo);
                mapa.remove(antigo.key);
            }
            var novo = new Node(key, value);
            mapa.put(key, novo);
            inserirNaFrente(novo);
        }

        private void moverParaFrente(Node n) {
            remover(n);
            inserirNaFrente(n);
        }

        private void remover(Node n) {
            n.prev.next = n.next;
            n.next.prev = n.prev;
        }

        private void inserirNaFrente(Node n) {
            n.next = head.next;
            n.prev = head;
            head.next.prev = n;
            head.next = n;
        }
    }
}

