import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void expulsaMenosRecente() {
        var c = new Solution.LRUCache(2);
        c.put(1, 1); c.put(2, 2);
        assertEquals(1, c.get(1));
        c.put(3, 3);
        assertEquals(-1, c.get(2));
        assertEquals(3, c.get(3));
    }

    @Test void atualizarChaveNaoCresce() {
        var c = new Solution.LRUCache(1);
        c.put(1, 1); c.put(1, 2);
        assertEquals(2, c.get(1));
    }

    @Test void getMarcaRecencia() {
        var c = new Solution.LRUCache(2);
        c.put(1, 1); c.put(2, 2);
        c.get(1); c.put(3, 3);
        assertEquals(-1, c.get(2));
        assertEquals(1, c.get(1));
    }
}
